# 网口不通时经串口取文件：分块 hexdump，逐行校验（偏移、16 字节、ASCII 栏与
# 字节一致），任一行不对整块重取。串口 1.5M 两个方向都会丢字符，命令逐字发。
import serial, sys, time, re

cmd, remote, out = sys.argv[1], sys.argv[2], sys.argv[3]
CH = 256
s = serial.Serial('/dev/ttyUSB0', 1500000, timeout=0.2)

def send(c):
    s.read(65536)
    for ch in c + '\r':
        s.write(ch.encode()); time.sleep(0.002)

def until_prompt(t=6):
    b = b''; e = time.time() + t
    while time.time() < e:
        b += s.read(65536)
        if b.rstrip().endswith(b'nsh>') or b'nsh> ' in b[-20:]:
            break
    return b.decode('latin1')

if cmd:
    send(cmd); until_prompt(3); time.sleep(3)

size = None
for _ in range(5):
    send('ls -l ' + remote)
    m = re.search(r'\s(\d+)\s+' + re.escape(remote), until_prompt())
    if m:
        size = int(m.group(1)); break
if size is None:
    sys.exit('读不到文件大小')

def asc(b):
    return ''.join(chr(x) if 32 <= x < 127 else '.' for x in b)

data = bytearray()
off = 0
while off < size:
    n = min(CH, size - off)
    for attempt in range(8):
        send('hexdump %s skip=%d count=%d' % (remote, off, n))
        txt = until_prompt()
        got = {}
        for line in txt.splitlines():
            m = re.match(r'^([0-9a-f]{4}): ((?:[0-9a-f]{2} ){1,16})(.*)$', line)
            if not m:
                continue
            b = bytes(int(x, 16) for x in m.group(2).split())
            a = m.group(3).strip('\r')
            if a.strip() != asc(b).strip():
                continue
            got[int(m.group(1), 16)] = b
        chunk = bytearray()
        ok = True
        for lo in range(0, n, 16):
            want = min(16, n - lo)
            if lo not in got or len(got[lo]) != want:
                ok = False; break
            chunk += got[lo]
        if ok:
            data += chunk; break
    else:
        sys.exit('偏移 %d 重试 8 次仍不完整' % off)
    off += n
    print('\r%d/%d' % (off, size), end='', flush=True)

open(out, 'wb').write(data)
print('\n', out, len(data))

