#define TOUCH_I2C_ADDR     0x38          /* 原厂日志的 0-0038 */

#define TOUCH_IRQ_BANK     BOARD_TP_INT_BANK
#define TOUCH_IRQ_PIN      BOARD_TP_INT_PIN
#define TOUCH_RST_BANK     BOARD_TP_RST_BANK
#define TOUCH_RST_PIN      BOARD_TP_RST_PIN

/****************************************************************************
