uint32_t rk3576_gpio_irq_count(int bank, uint32_t *last_status)
{
  if (bank < 0 || bank >= RK3576_GPIO_NBANKS)
    {
      return 0;
    }

  if (last_status != NULL)
    {
      *last_status = g_gpio_isr_last[bank];
