static int vision_snapshot(void)
{
  char *argv[] =
  {
    "v4l2cap", "1280", "720", VISION_JPEG, NULL
  };

  struct stat st;
  off_t last = -1;
  pid_t pid;
  int status = 0;
  int waited;
  int ret;

  unlink(VISION_JPEG);
  ret = posix_spawn(&pid, "v4l2cap", NULL, NULL, argv, NULL);
  if (ret != 0)
    {
      return -ret;
    }

  for (waited = 0; waited < 10000; waited += 100)
    {
      usleep(100 * 1000);
      waitpid(pid, &status, WNOHANG);

      if (stat(VISION_JPEG, &st) == 0 && st.st_size >= 1024)
        {
          if (st.st_size == last)
            {
              return (int)st.st_size;
            }

          last = st.st_size;
        }
    }

  syslog(LOG_ERR, "视觉: 10 秒内没拿到照片（%s）\n", VISION_JPEG);
  return -ETIMEDOUT;
}

static const char g_b64[] =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *b64_encode(const unsigned char *in, size_t len)
{
  size_t olen = (len + 2) / 3 * 4;
  char *out = malloc(olen + 1);
  char *w = out;
  size_t i;

  if (out == NULL)
    {
      return NULL;
    }

  for (i = 0; i + 2 < len; i += 3)
    {
      uint32_t v = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];

      *w++ = g_b64[(v >> 18) & 63];
      *w++ = g_b64[(v >> 12) & 63];
      *w++ = g_b64[(v >> 6) & 63];
      *w++ = g_b64[v & 63];
    }

  if (i < len)
    {
      uint32_t v = in[i] << 16;

      if (i + 1 < len)
        {
          v |= in[i + 1] << 8;
        }

      *w++ = g_b64[(v >> 18) & 63];

