  if (bpl / 2 < w)
    w = bpl / 2;
  if (fmt.fmt.pix_mp.plane_fmt[0].sizeimage / bpl < h)
    h = fmt.fmt.pix_mp.plane_fmt[0].sizeimage / bpl;
  printf("按 %ux%u（16 位/像素）解释\n", w, h);

