    *exposure = (int)((uint64_t)*exposure * AE_TARGET / net);
    if (*exposure > AE_EXP_MAX)
      *exposure = AE_EXP_MAX;
  } else if (steps < 0 && *gain == 0) {
    *exposure = (int)((uint64_t)*exposure * AE_TARGET / net);
    if (*exposure < AE_EXP_MIN)
      *exposure = AE_EXP_MIN;
  } else {
    *gain += steps;
    if (*gain < 0)
      *gain = 0;
    if (*gain > AE_GAIN_MAX)
      *gain = AE_GAIN_MAX;
