 */

#define HOME_N       6
#define HOME_WAIT_S  3
#define HOME_NOTE_S  3
#define HOME_BULB    0xffc857

static const struct
{
  const char *id;
  const char *icon;
  const char *name;
  uint32_t color;
}
g_home_dev[HOME_N] =
{
  { "living_light", ICON_BULB, "客厅灯", HOME_BULB },
  { "desk_lamp",    ICON_BULB, "台灯",   HOME_BULB },
